".metricsContainer {
  display: flex;
  flex-direction: column;
  gap: 24px;
  padding: 24px;
  background-color: var(--bg-primary);
  color: var(--text-primary);
  font-family: var(--font-mono, monospace);
  min-height: 100%;
}

.titleHeader {
  display: flex;
  justify-content: space-between;
  align-items: center;
  border-bottom: 2px solid var(--border-default, #00ff66);
  padding-bottom: 12px;
  flex-wrap: wrap;
  gap: 16px;
}

.titleInfo {
  display: flex;
  flex-direction: column;
  gap: 4px;

  h1 {
    font-size: 24px;
    font-weight: 700;
    letter-spacing: 1.5px;
    text-transform: uppercase;
    color: var(--text-primary);
    margin: 0;
  }
}

.barDeco {
  height: 10px;
  overflow: hidden;
  opacity: 0.8;
}

.chainBar {
  display: flex;
  gap: 8px;
}

.chainBtn {
  border: 1px solid var(--border-default, #00ff66) !important;
  background-color: transparent !important;
  color: var(--text-secondary, #88a090) !important;
  font-size: 11px !important;
  font-weight: bold !important;
  padding: 4px 10px !important;
  cursor: pointer;
  transition: all 0.1s ease;
  border-radius: 0 !important;

  &:hover {
    color: var(--text-primary) !important;
    background-color: rgba(0, 255, 102, 0.08) !important;
  }
}

.activeChain {
  color: var(--bg-primary) !important;
  background-color: var(--border-default, #00ff66) !important;
  box-shadow: 0 0 8px rgba(0, 255, 102, 0.3);

  &:hover {
    background-color: var(--border-default, #00ff66) !important;
    color: var(--bg-primary) !important;
  }
}

.alertError {
  display: flex;
  align-items: center;
  gap: 12px;
  background-color: rgba(255, 51, 51, 0.06);
  border: 1px solid #ff3333;
  padding: 12px 16px;
  color: #ff5555;
  font-size: 13px;
  font-weight: bold;
}

.alertDot {
  width: 8px;
  height: 8px;
  background-color: #ff3333;
  border-radius: 50%;
  animation: blink 1s infinite alternate;
}

